// Generated by QuantNight artifacts/bug_maintenance/rust_task_core_20261024/policy/generate_golden.py.
// Expected values come from AST-extracted ORIGINAL Python functions, not a port.
// Exercise the real registered library, not a duplicate path-imported module.
use mongodb::bson::{Bson, Document};
use quantnight_task_core::lifecycle_policy::*;
use serde_json::Value;

#[test]
fn original_python_pure_functions_match_rust_golden() {
    let fixtures: Vec<Value> = serde_json::from_str(GOLDEN).unwrap();
    for fixture in fixtures {
        let op = fixture["op"].as_str().unwrap();
        let label = fixture["label"].as_str().unwrap();
        let input = Bson::try_from(fixture["input"].clone()).unwrap();
        let empty = Document::new();
        let row = input.as_document().unwrap_or(&empty);
        let actual: Result<Bson, String> = match op {
            "validate_name" => {
                validate_name(fixture["name"].as_str().unwrap()).map(|_| Bson::Boolean(true))
            }
            "task_binding_query" => task_binding_query(
                fixture["name"].as_str().unwrap(),
                row,
                fixture["command"].as_str().unwrap(),
            )
            .map(Bson::Document),
            "receipt_evidence" | "checked_receipt_evidence" => {
                checked_receipt_evidence(row).map(Bson::Boolean)
            }
            "positively_unposted" | "checked_positively_unposted" => {
                checked_positively_unposted(row).map(Bson::Boolean)
            }
            "unresolved_execution_row" | "checked_unresolved_execution_row" => {
                checked_unresolved_execution_row(row).map(Bson::Boolean)
            }
            "stop_confirmation_valid" => Ok(Bson::Boolean(stop_confirmation_valid(
                row,
                fixture["remote"].as_bool().unwrap(),
            ))),
            "assert_observation_closed" => {
                assert_observation_closed(row).map(|_| Bson::Boolean(true))
            }
            _ => panic!("unknown fixture operation: {op}"),
        };
        let expected = &fixture["expected"];
        // Legacy APIs preserve successes, and only collapse actual errors to
        // conservative outcomes (never treat corrupt evidence as no-POST).
        let compatibility = match op.trim_start_matches("checked_") {
            "receipt_evidence" => Some((receipt_evidence(row), true)),
            "positively_unposted" => Some((positively_unposted(row), false)),
            "unresolved_execution_row" => Some((unresolved_execution_row(row), true)),
            _ => None,
        };
        if let Some((legacy, fallback)) = compatibility {
            assert_eq!(
                legacy,
                actual
                    .as_ref()
                    .map(|v| v.as_bool().unwrap())
                    .unwrap_or(fallback),
                "legacy {op}: {label}"
            );
        }
        if let Some(error) = expected.get("error") {
            assert_eq!(
                actual,
                Err(error.as_str().unwrap().to_string()),
                "{op}: {label}"
            );
        } else {
            let value = Bson::try_from(expected["value"].clone()).unwrap();
            assert_eq!(actual, Ok(value), "{op}: {label}");
        }
    }
}

